FFStatus Session::doLogout(std::string_view reason) noexcept {
	std::lock_guard<std::recursive_mutex> lock(m_mutex);

	if (m_state.closing() ||
		m_state.status == falconfix::SessionStatus::Disconnected) {
		return FF_OK();
	}

	if (m_state.awaitingResend) {
		m_state.status = falconfix::SessionStatus::Closing;
		return FF_OK();
	}

	return sendLogout(reason);
}

