FFStatus Session::sendSequenceResetGapFill(int64_t msgSeqNum, int64_t newSeqNo) noexcept {
	fix43::messages::SequenceReset msg;

	msg.getRefHeader().setMsgSeqNum(msgSeqNum);

	msg.setGapFillFlag(true);
	msg.setNewSeqNo(newSeqNo);

	FFStatus rc = prepareOutboundWithoutSeqOverride(msg, m_sid);
	if (!rc.ok()) [[unlikely]] {
		return rc;
	}

	rc = msg.toString(m_out, m_cfg.connection.millisecondsInTimeStamp);
	if (!rc.ok()) [[unlikely]] {
		return rc;
	}

	rc = connection().write(m_out.data(), m_out.size());
	if (!rc.ok()) [[unlikely]] {
		return rc;
	}

	m_state.lastSentMs = falconfix::TickClock::getTickCount();

	m_log->outgoing(m_sidText, {m_out.data(), m_out.size()});
	m_log->event(m_sidText, "sequence reset gap-fill sent");

	return FF_OK();
}

FFStatus Session::sendReject(int64_t refSeqNum,
							 int32_t refTagID,
							 std::string_view text,
							 fix43::enums::SessionRejectReason reason) noexcept {
	fix43::messages::Reject msg;

	msg.setRefSeqNum(static_cast<fix43::types::INT>(refSeqNum));

	msg.setSessionRejectReason(static_cast<fix43::types::INT>(reason));

	if (refTagID > 0) {
		msg.setRefTagID(static_cast<fix43::types::INT>(refTagID));
	}

	if (!text.empty()) {
		msg.setText(text);
	}

	return send(msg);
}

